# -*- coding: utf-8 -*-
"""docs/6.1-平台素材清单.docx —— 按 game-docs-and-sheets-inventory.md 6.1【S 必需】写。

清单要求：标题、简介、封面图尺寸、截图张数、标签、链接；每个平台的尺寸与字数限制提前查清。

## 诚实边界
虎扑 AI 工坊的**具体投稿规范（封面尺寸、字数上限、标签数量、审核时长）我没有可靠来源**，
所以一律标「待你查」，不编数字。填完后这份文档就是投稿当天的 checklist。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "6.1-平台素材清单.docx")


